ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2 ImageFileName=/(vssadmin|wmic|bcdedit|wbadmin|net)\.exe$/i
| Technique := case {
    regex("(?i)vssadmin\\.exe", field=ImageFileName) AND regex("(?i)delete\\s+shadows", field=CommandLine) | "VSSAdmin-DeleteShadows";
    regex("(?i)wmic\\.exe", field=ImageFileName) AND regex("(?i)shadowcopy.*delete", field=CommandLine) | "WMIC-ShadowCopyDelete";
    regex("(?i)bcdedit\\.exe", field=ImageFileName) AND regex("(?i)(bootstatuspolicy\\s+ignoreallfailures|recoveryenabled\\s+no)", field=CommandLine) | "BCDEdit-DisableRecovery";
    regex("(?i)wbadmin\\.exe", field=ImageFileName) AND regex("(?i)delete\\s+catalog", field=CommandLine) | "WBAdmin-DeleteCatalog";
    regex("(?i)net\\.exe", field=ImageFileName) AND regex("(?i)stop\\s+", field=CommandLine) AND regex("(?i)(MSExchange|MSSQL|SQLAgent|Veeam|Backup|VSS|BackupExec)", field=CommandLine) | "Net-StopBackupService";
    * | ""
}
| Technique!=""
| groupBy([aid, ComputerName, UserName], function=[count(field=Technique, distinct=true, as=TechniqueCount), collect([Technique, CommandLine]), min(_time, as=FirstSeen), max(_time, as=LastSeen)])
| TechniqueCount >= 2
| sort(LastSeen, order=desc)
